'use client';

import {
  Editable as EditablePrimitive,
  useEditable,
  useEditableContext,
} from '@ark-ui/react/editable';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { CheckIcon, CloseIcon, PencilIcon } from '@/lib/moduix/icons/ui';
import styles from './Editable.module.css';

const Editable = forwardRef<
  ComponentRef<typeof EditablePrimitive.Root>,
  ComponentProps<typeof EditablePrimitive.Root>
>(function Editable({ activationMode = 'dblclick', className, ...props }, ref) {
  return (
    <EditablePrimitive.Root
      ref={ref}
      activationMode={activationMode}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="editable-root"
    />
  );
});

const EditableRootProvider = forwardRef<
  ComponentRef<typeof EditablePrimitive.RootProvider>,
  ComponentProps<typeof EditablePrimitive.RootProvider>
>(function EditableRootProvider({ className, ...props }, ref) {
  return (
    <EditablePrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="editable-root-provider"
    />
  );
});

const EditableLabel = forwardRef<
  ComponentRef<typeof EditablePrimitive.Label>,
  ComponentProps<typeof EditablePrimitive.Label>
>(function EditableLabel({ className, ...props }, ref) {
  return (
    <EditablePrimitive.Label
      ref={ref}
      className={clsx(styles.label, className)}
      {...props}
      data-slot="editable-label"
    />
  );
});

const EditableArea = forwardRef<
  ComponentRef<typeof EditablePrimitive.Area>,
  ComponentProps<typeof EditablePrimitive.Area>
>(function EditableArea({ className, ...props }, ref) {
  return (
    <EditablePrimitive.Area
      ref={ref}
      className={clsx(styles.area, className)}
      {...props}
      data-slot="editable-area"
    />
  );
});

const EditableInput = forwardRef<
  ComponentRef<typeof EditablePrimitive.Input>,
  ComponentProps<typeof EditablePrimitive.Input>
>(function EditableInput({ className, ...props }, ref) {
  return (
    <EditablePrimitive.Input
      ref={ref}
      className={clsx(styles.input, className)}
      {...props}
      data-slot="editable-input"
    />
  );
});

const EditablePreview = forwardRef<
  ComponentRef<typeof EditablePrimitive.Preview>,
  ComponentProps<typeof EditablePrimitive.Preview>
>(function EditablePreview({ className, ...props }, ref) {
  return (
    <EditablePrimitive.Preview
      ref={ref}
      className={clsx(styles.preview, className)}
      {...props}
      data-slot="editable-preview"
    />
  );
});

const EditableControl = forwardRef<
  ComponentRef<typeof EditablePrimitive.Control>,
  ComponentProps<typeof EditablePrimitive.Control>
>(function EditableControl({ className, ...props }, ref) {
  return (
    <EditablePrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="editable-control"
    />
  );
});

const EditableEditTrigger = forwardRef<
  ComponentRef<typeof EditablePrimitive.EditTrigger>,
  ComponentProps<typeof EditablePrimitive.EditTrigger>
>(function EditableEditTrigger({ asChild, className, children, ...props }, ref) {
  return (
    <EditablePrimitive.EditTrigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.trigger, className)}
      {...props}
      data-slot="editable-edit-trigger"
    >
      {children ?? <PencilIcon />}
    </EditablePrimitive.EditTrigger>
  );
});

const EditableSubmitTrigger = forwardRef<
  ComponentRef<typeof EditablePrimitive.SubmitTrigger>,
  ComponentProps<typeof EditablePrimitive.SubmitTrigger>
>(function EditableSubmitTrigger({ asChild, className, children, ...props }, ref) {
  return (
    <EditablePrimitive.SubmitTrigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.trigger, className)}
      {...props}
      data-slot="editable-submit-trigger"
    >
      {children ?? <CheckIcon />}
    </EditablePrimitive.SubmitTrigger>
  );
});

const EditableCancelTrigger = forwardRef<
  ComponentRef<typeof EditablePrimitive.CancelTrigger>,
  ComponentProps<typeof EditablePrimitive.CancelTrigger>
>(function EditableCancelTrigger({ asChild, className, children, ...props }, ref) {
  return (
    <EditablePrimitive.CancelTrigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.trigger, className)}
      {...props}
      data-slot="editable-cancel-trigger"
    >
      {children ?? <CloseIcon />}
    </EditablePrimitive.CancelTrigger>
  );
});

const EditableControls = forwardRef<
  ComponentRef<typeof EditablePrimitive.Control>,
  Omit<ComponentProps<typeof EditablePrimitive.Control>, 'asChild' | 'children'>
>(function EditableControls(props, ref) {
  const editable = useEditableContext();

  return (
    <EditableControl ref={ref} {...props}>
      {editable.editing ? (
        <>
          <EditableSubmitTrigger />
          <EditableCancelTrigger />
        </>
      ) : (
        <EditableEditTrigger />
      )}
    </EditableControl>
  );
});

const EditableContext = EditablePrimitive.Context;

export {
  Editable,
  EditableArea,
  EditableCancelTrigger,
  EditableContext,
  EditableControl,
  EditableControls,
  EditableEditTrigger,
  EditableInput,
  EditableLabel,
  EditablePreview,
  EditableRootProvider,
  EditableSubmitTrigger,
  useEditable,
  useEditableContext,
};

export type {
  EditableAreaProps,
  EditableCancelTriggerProps,
  EditableContextProps,
  EditableControlProps,
  EditableEditChangeDetails,
  EditableEditTriggerProps,
  EditableFocusOutsideEvent,
  EditableInputProps,
  EditableInteractOutsideEvent,
  EditableLabelProps,
  EditablePointerDownOutsideEvent,
  EditablePreviewProps,
  EditableRootProps,
  EditableRootProviderProps,
  EditableSubmitTriggerProps,
  EditableValueChangeDetails,
  UseEditableContext,
  UseEditableProps,
  UseEditableReturn,
} from '@ark-ui/react/editable';

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: start;
    gap: var(--moduix-spacing-1);
    width: 100%;
    color: var(--moduix-color-foreground);

    &:has([data-autoresize]) {
      width: fit-content;
      max-width: 100%;
    }

    &:has([data-disabled]) {
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled]
        )
        & {
        opacity: 1;
      }
    }
  }

  .label {
    grid-column: 1 / -1;
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-1);
    overflow-wrap: anywhere;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);

    &[data-invalid] {
      color: var(--moduix-color-destructive);
    }
  }

  .area {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    min-width: 0;
    min-height: var(--moduix-editable-area-height, var(--moduix-size-md));
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3-5);
    background-color: var(--moduix-color-background);
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &:is([data-focus], :has(:focus-visible)) {
      outline-color: var(--moduix-color-ring);
    }

    &:has([data-invalid]) {
      border-color: var(--moduix-color-destructive);

      &:is([data-focus], :has(:focus-visible)) {
        outline-color: var(--moduix-color-destructive);
      }
    }

    &[data-disabled] {
      pointer-events: none;
    }
  }

  .input,
  .preview {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    margin: 0;
    border: 0;
    padding: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    outline: 0;
  }

  .input {
    appearance: none;

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }

    &:is(textarea) {
      min-height: 6rem;
      resize: vertical;
    }
  }

  .preview {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    cursor: text;

    &[data-placeholder-shown] {
      color: var(--moduix-color-muted-foreground);
    }

    &:is([data-disabled], [aria-readonly='true']) {
      cursor: default;
    }
  }

  .control {
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-1);
  }

  .trigger {
    box-sizing: border-box;
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    width: var(--moduix-editable-area-height, var(--moduix-size-md));
    height: var(--moduix-editable-area-height, var(--moduix-size-md));
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-sm);
    padding: 0;
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-color-accent);
      }
    }

    &:active {
      background-color: var(--moduix-color-accent);
    }

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }

    &:disabled {
      pointer-events: none;
    }

    & > svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
      flex-shrink: 0;
    }
  }
}
